create or replace function public.enforce_schoolpro_result_lock() returns trigger language plpgsql as $$ begin if old.locked=true and new.locked=true and (to_jsonb(new)-'locked'-'updated_at') is distinct from (to_jsonb(old)-'locked'-'updated_at') then raise exception 'Result is locked'; end if; return new; end $$; drop trigger if exists trg_schoolpro_result_lock on public.schoolpro_results; create trigger trg_schoolpro_result_lock before update on public.schoolpro_results for each row execute function public.enforce_schoolpro_result_lock();